cd /app && python3 - <<'PY'
import json, subprocess, sys
def run(s):
    p=subprocess.run([sys.executable,'/app/submission/bridge.py'],input=json.dumps(s).encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    if p.returncode: return ('ERR',p.stderr.decode())
    return json.loads(p.stdout)
def H(sid,f): return {'sid':sid,'type':'headers','fields':f}
def F(sid): return {'sid':sid,'type':'fin'}
def D(sid,h): return {'sid':sid,'type':'data','hex':h}
def U(sid): return {'sid':sid,'type':'unknown','frame_type':33,'hex':'00'}
print('empty', run({'routes':{},'events':[]}))
# only fin
print('onlyfin', run({'routes':{'https://a.test':'o'},'events':[F(0)]})['streams'])
# only unknown then incomplete
print('unkonly', run({'routes':{'https://a.test':'o'},'events':[U(0)]})['streams'])
# fin first then other stream forwarded; commit ordering & offsets
s={'routes':{'https://a.test':'o'},'events':[
  H(4,[[':method','GET'],[':scheme','https'],[':authority','a.test'],[':path','/x']]),
  H(0,[[':method','GET'],[':scheme','https'],[':authority','a.test'],[':path','/y']]),
  F(4), F(0)]}
r=run(s); 
for st in r['streams']: print('order', st['sid'], st['status'], st['offset'], st['length'])
# multiple routes same origin + unused
s={'routes':{'https://a.test':'o','https://b.test':'o','https://c.test':'z'},'events':[H(0,[[':method','GET'],[':scheme','https'],[':authority','b.test'],[':path','/q']]),F(0)]}
r=run(s); print('origins keys', sorted(r['origins']), 'o len', len(bytes.fromhex(r['origins']['o'])))
# reset ends regardless of earlier content
s={'routes':{'https://a.test':'o'},'events':[H(0,[[':method','BOGUS'],[':scheme','x'],[':authority','x'],[':path','bad']]),R:= {'sid':0,'type':'reset'}]}
print('resetbad', run(s)['streams'])
